package cosmic.browser;

import java.util.Arrays;
import java.util.Locale;

/** 定義済みの小さなJava演習だけを実行する。入力をコードとして評価する機能は持たない。 */
public final class PracticeEngine {

  private PracticeEngine() {}

  public static String run(String exercise, String input) {
    if (input == null || input.length() > 160) return failure(
      "入力は160文字以内にしてください。"
    );
    try {
      return switch (exercise == null ? "" : exercise) {
        case "clamp" -> clamp(input);
        case "filter" -> filter(input);
        case "copy" -> copy(input);
        case "json" -> success(
          quote(input),
          "文字列の値と、JSONに書き出す表現を区別します。二重引用符・改行・バックスラッシュを確認してください。"
        );
        default -> failure("この演習は見つかりません。");
      };
    } catch (NumberFormatException e) {
      return failure(
        "整数として読み取れません。小数・空欄・intの範囲を超える値を確認してください。"
      );
    }
  }

  private static String clamp(String input) {
    int value = parseInteger(input);
    int result = Math.max(0, Math.min(100, value));
    return success(
      Integer.toString(result),
      "数字を半角の0〜9へ揃えて整数に変換し、0〜100に収めます。変換できない入力は、範囲を調整する前にエラーになります。"
    );
  }

  private static String filter(String input) {
    String query = input.trim().toLowerCase(Locale.ROOT);
    String[] source = {
      "Java / HTTP",
      "Java / record",
      "Java / browser",
      "Rust / ownership",
      "GLSL / light",
    };
    StringBuilder result = new StringBuilder("[");
    for (String item : source)
      if (item.toLowerCase(Locale.ROOT).contains(query)) {
        if (result.length() > 1) result.append(", ");
        result.append(item);
      }
    return success(
      result.append(']').toString(),
      "trimと小文字化の後に部分一致で絞ります。空文字は全件に一致します。全角と半角をそろえる処理は、この演習には含めていません。"
    );
  }

  private static String copy(String input) {
    String[] parts = input.split(",", -1);
    if (parts.length > 12) return failure("配列は12個以内にしてください。");
    int[] original = new int[parts.length];
    for (int i = 0; i < parts.length; i++) original[i] = parseInteger(parts[i]);
    int[] sorted = Arrays.copyOf(original, original.length);
    Arrays.sort(sorted);
    return success(
      "元の配列: " +
        Arrays.toString(original) +
        "\n並べ替え後: " +
        Arrays.toString(sorted),
      "コピーした配列だけを並べ替えています。sorted = originalに変えたら、結果はどう変わるでしょうか。"
    );
  }

  public static int reviewDays(int successes, boolean recalled) {
    if (!recalled) return 1;
    int[] days = { 1, 3, 7, 14, 30 };
    return days[Math.max(0, Math.min(days.length - 1, successes))];
  }

  /**
   * TeaVM 0.16のparseIntはASCII数字だけを読むため、Unicodeの十進数字を先に揃える。
   * isDigitで十進数字に限定し、ローマ数字や上付き数字を整数として受け入れない。
   * 符号とintの範囲の判定はInteger.parseIntに任せる。
   */
  static int parseInteger(String raw) {
    String value = raw.trim();
    StringBuilder ascii = new StringBuilder();
    for (int i = 0; i < value.length(); i++) {
      char c = value.charAt(i);
      if (i == 0 && (c == '+' || c == '-')) {
        ascii.append(c);
      } else {
        if (!Character.isDigit(c)) throw new NumberFormatException();
        int digit = Character.digit(c, 10);
        if (digit < 0 || digit > 9) throw new NumberFormatException();
        ascii.append((char) ('0' + digit));
      }
    }
    return Integer.parseInt(ascii.toString());
  }

  private static String success(String value, String explanation) {
    return (
      "{\"ok\":true,\"result\":" +
      quote(value) +
      ",\"explanation\":" +
      quote(explanation) +
      "}"
    );
  }

  private static String failure(String message) {
    return (
      "{\"ok\":false,\"result\":" +
      quote(message) +
      ",\"explanation\":\"入力を変えてもう一度試せます。\"}"
    );
  }

  static String quote(String value) {
    StringBuilder out = new StringBuilder("\"");
    char[] hex = "0123456789abcdef".toCharArray();
    for (int i = 0; i < value.length(); i++) {
      char c = value.charAt(i);
      if (c == '"' || c == '\\') out.append('\\').append(c);
      else if (c < 32) out
        .append("\\u00")
        .append(hex[c >> 4])
        .append(hex[c & 15]);
      else out.append(c);
    }
    return out.append('"').toString();
  }
}

package learning.books.http;

import java.util.Optional;
import java.util.UUID;
import java.util.function.Supplier;

/**
 * 処理の判断を行う層。HTTP の言葉（ステータスコード）は持たず、
 * 結果の種類（sealed 型）で Controller へ返す。
 */
public final class BookService {
    public sealed interface GetResult {
        record Found(Book book) implements GetResult { }
        record BadInput(String reason) implements GetResult { }
        record Missing(int id) implements GetResult { }
        record Failure(String requestId) implements GetResult { }
    }

    public sealed interface UpdateResult {
        record Updated(Book book) implements UpdateResult { }
        record BadInput(String reason) implements UpdateResult { }
        record Missing(int id) implements UpdateResult { }
        record Conflict(int id) implements UpdateResult { }
        record Failure(String requestId) implements UpdateResult { }
    }

    private final BookRepository repository;
    private final Supplier<String> requestIds;

    public BookService(BookRepository repository) {
        this(repository, () -> UUID.randomUUID().toString());
    }

    BookService(BookRepository repository, Supplier<String> requestIds) {
        this.repository = repository;
        this.requestIds = requestIds;
    }

    public static Optional<Integer> parseId(String raw) {
        if (raw == null || !raw.matches("[1-9][0-9]{0,5}")) return Optional.empty();
        return Optional.of(Integer.parseInt(raw));
    }

    public GetResult get(String rawId) {
        return get(rawId, requestIds.get());
    }

    /** requestId は HTTP 層で発行されたものをそのまま使う（検証→業務判断→保存→応答を1つの ID で追う）。 */
    public GetResult get(String rawId, String requestId) {
        Optional<Integer> id = parseId(rawId);
        if (id.isEmpty()) return new GetResult.BadInput("IDは1以上の整数にしてください");
        try {
            return repository.findById(id.get())
                    .<GetResult>map(GetResult.Found::new)
                    .orElseGet(() -> new GetResult.Missing(id.get()));
        } catch (RepositoryException e) {
            // 内部の詳細はサーバ側ログだけに残し、応答には含めない（Q: DB失敗シナリオと対応）
            System.err.println("[book-api] requestId=" + requestId + " stage=storage result=failure detail=" + e.getMessage());
            return new GetResult.Failure(requestId);
        }
    }

    public UpdateResult rename(String rawId, String title, String rawVersion) {
        return rename(rawId, title, rawVersion, requestIds.get());
    }

    public UpdateResult rename(String rawId, String title, String rawVersion, String requestId) {
        Optional<Integer> id = parseId(rawId);
        if (id.isEmpty()) return new UpdateResult.BadInput("IDは1以上の整数にしてください");
        if (title == null || title.isBlank()) return new UpdateResult.BadInput("titleは必須です");
        final int version;
        try {
            version = Integer.parseInt(rawVersion == null ? "" : rawVersion.trim());
        } catch (NumberFormatException e) {
            return new UpdateResult.BadInput("versionは整数にしてください");
        }
        try {
            if (repository.findById(id.get()).isEmpty()) return new UpdateResult.Missing(id.get());
            boolean ok = repository.updateTitle(id.get(), title.trim(), version);
            if (!ok) return new UpdateResult.Conflict(id.get());
            return repository.findById(id.get())
                    .<UpdateResult>map(UpdateResult.Updated::new)
                    .orElseGet(() -> new UpdateResult.Failure(requestId));
        } catch (RepositoryException e) {
            System.err.println("[book-api] requestId=" + requestId + " stage=storage result=failure detail=" + e.getMessage());
            return new UpdateResult.Failure(requestId);
        }
    }
}

package learning.books.http;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Optional;

/**
 * JDBC + SQLite の実装。コンパイルに外部 jar は不要（java.sql は JDK 同梱）。
 * 実行時だけ SQLite JDBC ドライバ（org.xerial:sqlite-jdbc）をクラスパスへ置く。
 * SQL は PreparedStatement の ? へ値をバインドし、文字列結合で組み立てない。
 */
public final class JdbcBookRepository implements BookRepository {
    private final String jdbcUrl;

    public JdbcBookRepository(String jdbcUrl) {
        this.jdbcUrl = jdbcUrl;
        try (Connection con = open(); Statement st = con.createStatement()) {
            st.executeUpdate("CREATE TABLE IF NOT EXISTS books ("
                    + "id INTEGER PRIMARY KEY, title TEXT NOT NULL, version INTEGER NOT NULL)");
        } catch (SQLException e) {
            throw new RepositoryException("schema initialization failed", e);
        }
    }

    private Connection open() throws SQLException {
        return DriverManager.getConnection(jdbcUrl);
    }

    @Override
    public Optional<Book> findById(int id) {
        String sql = "SELECT id, title, version FROM books WHERE id = ?";
        try (Connection con = open(); PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) return Optional.empty();
                return Optional.of(new Book(rs.getInt("id"), rs.getString("title"), rs.getInt("version")));
            }
        } catch (SQLException e) {
            throw new RepositoryException("findById failed", e);
        }
    }

    @Override
    public Book insert(String title) {
        String sql = "INSERT INTO books (title, version) VALUES (?, 1)";
        try (Connection con = open();
             PreparedStatement ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, title);
            ps.executeUpdate();
            try (ResultSet keys = ps.getGeneratedKeys()) {
                if (!keys.next()) throw new RepositoryException("no generated key", null);
                int id = keys.getInt(1);
                return new Book(id, title, 1);
            }
        } catch (SQLException e) {
            throw new RepositoryException("insert failed", e);
        }
    }

    /** 明示 id での初期データ投入用（存在すれば何もしない）。 */
    public void seed(int id, String title) {
        String sql = "INSERT OR IGNORE INTO books (id, title, version) VALUES (?, ?, 1)";
        try (Connection con = open(); PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setInt(1, id);
            ps.setString(2, title);
            ps.executeUpdate();
        } catch (SQLException e) {
            throw new RepositoryException("seed failed", e);
        }
    }

    @Override
    public boolean updateTitle(int id, String title, int expectedVersion) {
        // WHERE 句の version 条件が楽観ロック。更新件数 0 は「古い version への同時更新」を表す。
        String sql = "UPDATE books SET title = ?, version = version + 1 WHERE id = ? AND version = ?";
        try (Connection con = open(); PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setString(1, title);
            ps.setInt(2, id);
            ps.setInt(3, expectedVersion);
            return ps.executeUpdate() == 1;
        } catch (SQLException e) {
            throw new RepositoryException("updateTitle failed", e);
        }
    }
}

//! 銀河の形をつくる小さな数理モデル。天体物理の正確なシミュレーションではありません。
//! 純粋関数で形を生成し、同じ実装をネイティブのテスト・HTTP API・Wasmで利用します。
use std::f32::consts::TAU;
use std::sync::Mutex;

pub const MAX_PARTICLES: usize = 32000;
pub const STRIDE: usize = 4;

/// x, y, z, brightness を連続するf32として返す。seedが同じなら結果も同じです。
pub fn galaxy(count: usize, seed: u32) -> Vec<f32> {
    let count = count.min(MAX_PARTICLES);
    let mut state = seed.max(1);
    let mut random = || {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        state as f32 / u32::MAX as f32
    };
    let mut out = Vec::with_capacity(count * STRIDE);
    for i in 0..count {
        let central = i % 5 == 0;
        let r = if central {
            random().powi(2) * 0.28
        } else {
            random().powf(0.65)
        };
        let arm = (i % 2) as f32 * TAU / 2.0;
        let angle = if !central && i % 4 == 0 {
            random() * TAU
        } else {
            // Keep two recognisable arms, with a diffuse population between
            // them. This is an illustrative density model, not an N-body run.
            arm + r * 5.7 + (random() + random() + random() - 1.5) * (0.40 + r * 0.50)
        };
        let scatter = (1.0 - r) * 0.07;
        out.extend_from_slice(&[
            r * angle.cos() + (random() - 0.5) * scatter,
            r * angle.sin() + (random() - 0.5) * scatter,
            (random() + random() - 1.0)
                * if central {
                    0.13
                } else {
                    0.024 + (1.0 - r) * 0.025
                },
            0.35 + random() * 0.65,
        ]);
    }
    out
}

/// 描画用の降着円盤・背景の星。重力計算ではなく、上限付きの再現可能な形の生成。
pub fn cloud(mode: u32, count: usize, seed: u32) -> Vec<f32> {
    if mode == 0 || mode == 2 {
        return galaxy(count, seed);
    }
    let mut state = seed.max(1);
    let mut random = || {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        state as f32 / u32::MAX as f32
    };
    let mut out = Vec::with_capacity(count.min(MAX_PARTICLES) * STRIDE);
    for _ in 0..count.min(MAX_PARTICLES) {
        let angle = random() * TAU;
        if mode == 1 {
            let r = 0.235 + random().powf(0.8) * 0.85;
            out.extend_from_slice(&[
                r * angle.cos(),
                r * angle.sin(),
                (random() + random() - 1.0) * 0.018,
                0.3 + random() * 0.7,
            ]);
        } else {
            let z = random() * 2.0 - 1.0;
            let radius = 6.0 + random() * 9.0;
            let horizontal = (1.0 - z * z).sqrt();
            out.extend_from_slice(&[
                radius * horizontal * angle.cos(),
                radius * horizontal * angle.sin(),
                radius * z,
                0.2 + random() * 0.8,
            ]);
        }
    }
    out
}

/// 入力を上限付きで解釈する。巨大な要求でメモリを使い切らないための境界です。
pub fn requested_count(value: &str) -> Result<usize, &'static str> {
    let count: usize = value.parse().map_err(|_| "count must be an integer")?;
    if !(1..=MAX_PARTICLES).contains(&count) {
        return Err("count must be 1..32000");
    }
    Ok(count)
}

// Wasmは1つのブラウザページの中だけで利用。Rustがメモリを所有します。
// JSは次のgenerateを呼ぶまでの間だけFloat32Arrayで借りて読み取ります。
static BUFFER: Mutex<Vec<f32>> = Mutex::new(Vec::new());

#[unsafe(no_mangle)]
pub extern "C" fn galaxy_generate(count: u32, seed: u32) -> u32 {
    let mut buffer = BUFFER.lock().unwrap_or_else(|e| e.into_inner());
    *buffer = galaxy(count as usize, seed);
    (buffer.len() / STRIDE) as u32
}

#[unsafe(no_mangle)]
pub extern "C" fn cosmic_generate(mode: u32, count: u32, seed: u32) -> u32 {
    let mut buffer = BUFFER.lock().unwrap_or_else(|e| e.into_inner());
    *buffer = cloud(mode, count as usize, seed);
    (buffer.len() / STRIDE) as u32
}

#[unsafe(no_mangle)]
pub extern "C" fn galaxy_ptr() -> *const f32 {
    BUFFER.lock().unwrap_or_else(|e| e.into_inner()).as_ptr()
}

#[unsafe(no_mangle)]
pub extern "C" fn galaxy_len() -> u32 {
    BUFFER.lock().unwrap_or_else(|e| e.into_inner()).len() as u32
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn same_seed_is_reproducible() {
        assert_eq!(galaxy(100, 42), galaxy(100, 42));
    }
    #[test]
    fn different_seed_changes_shape() {
        assert_ne!(galaxy(100, 42), galaxy(100, 43));
    }
    #[test]
    fn all_points_are_finite_and_bounded() {
        let g = galaxy(MAX_PARTICLES, 7);
        assert_eq!(g.len(), MAX_PARTICLES * STRIDE);
        for p in g.as_chunks::<STRIDE>().0 {
            assert!(p.iter().all(|v| v.is_finite()));
            assert!(p[0].abs() < 1.1 && p[1].abs() < 1.1 && p[2].abs() < 0.2);
            assert!((0.35..=1.0).contains(&p[3]));
        }
    }
    #[test]
    fn large_request_is_clamped_without_allocating_it() {
        assert_eq!(galaxy(usize::MAX, 1).len(), MAX_PARTICLES * STRIDE);
    }
    #[test]
    fn zero_points_is_empty() {
        assert!(galaxy(0, 1).is_empty());
    }
    #[test]
    fn zero_seed_remains_useful() {
        assert!(galaxy(20, 0).windows(4).any(|p| p[0] != p[1]));
    }
    #[test]
    fn count_boundaries() {
        assert_eq!(requested_count("1"), Ok(1));
        assert_eq!(requested_count("32000"), Ok(32000));
        assert!(requested_count("32001").is_err());
    }
    #[test]
    fn invalid_count_does_not_become_zero() {
        for s in ["0", "-1", "x", "1.2", "9999999999999999999999999999"] {
            assert!(requested_count(s).is_err());
        }
    }
    #[test]
    fn cloud_modes_are_bounded_finite_and_reproducible() {
        for mode in [1, 2, 3, u32::MAX] {
            let a = cloud(mode, MAX_PARTICLES, 42);
            assert_eq!(a, cloud(mode, MAX_PARTICLES, 42));
            assert_eq!(a.len(), MAX_PARTICLES * STRIDE);
            assert!(a.iter().all(|x| x.is_finite()));
            assert!(a.iter().all(|x| x.abs() <= 15.1));
        }
    }
    #[test]
    fn accretion_disk_preserves_central_hole() {
        for p in cloud(1, 1000, 7).as_chunks::<STRIDE>().0 {
            let r = (p[0] * p[0] + p[1] * p[1]).sqrt();
            assert!((0.234..1.086).contains(&r));
            assert!(p[2].abs() < 0.019);
        }
        assert!(cloud(1, 0, 1).is_empty());
    }
}

//! 処理の判断を行う層。HTTP の言葉（ステータスコード）は持たず、結果の種類で handler へ返す。

use crate::model::Book;
use crate::repository::{BookRepository, RepositoryError};

#[derive(Debug, PartialEq)]
pub enum GetResult {
    Found(Book),
    BadInput(&'static str),
    Missing(i64),
    Failure(u64),
}

#[derive(Debug, PartialEq)]
pub enum UpdateResult {
    Updated(Book),
    BadInput(&'static str),
    Missing(i64),
    Conflict(i64),
    Failure(u64),
}

pub fn parse_id(raw: &str) -> Option<i64> {
    // Java 教材と同じ契約: 先頭が 0 でない 1〜6 桁の10進数
    let bytes = raw.as_bytes();
    if bytes.is_empty() || bytes.len() > 6 {
        return None;
    }
    if !bytes.iter().all(|b| b.is_ascii_digit()) || bytes[0] == b'0' {
        return None;
    }
    raw.parse::<i64>().ok()
}

pub struct BookService<'a> {
    repository: &'a dyn BookRepository,
}

impl<'a> BookService<'a> {
    pub fn new(repository: &'a dyn BookRepository) -> Self {
        BookService { repository }
    }

    /// request_id は HTTP 層で発行されたものをそのまま使う（検証→業務判断→保存→応答を1つの ID で追う）。
    fn failure(&self, e: RepositoryError, request_id: u64) -> u64 {
        // 内部の詳細はサーバ側ログだけに残し、応答には含めない
        eprintln!("[book-api-rs] requestId={} stage=storage result=failure detail={}", request_id, e.0);
        request_id
    }

    pub fn get(&self, raw_id: &str, request_id: u64) -> GetResult {
        let Some(id) = parse_id(raw_id) else {
            return GetResult::BadInput("IDは1以上の整数にしてください");
        };
        match self.repository.find_by_id(id) {
            Ok(Some(book)) => GetResult::Found(book),
            Ok(None) => GetResult::Missing(id),
            Err(e) => GetResult::Failure(self.failure(e, request_id)),
        }
    }

    pub fn rename(&self, raw_id: &str, title: Option<&str>, raw_version: Option<&str>, request_id: u64) -> UpdateResult {
        let Some(id) = parse_id(raw_id) else {
            return UpdateResult::BadInput("IDは1以上の整数にしてください");
        };
        let Some(title) = title.map(str::trim).filter(|t| !t.is_empty()) else {
            return UpdateResult::BadInput("titleは必須です");
        };
        let Some(version) = raw_version.and_then(|v| v.trim().parse::<i64>().ok()) else {
            return UpdateResult::BadInput("versionは整数にしてください");
        };
        match self.repository.find_by_id(id) {
            Ok(None) => UpdateResult::Missing(id),
            Ok(Some(_)) => match self.repository.update_title(id, title, version) {
                Ok(false) => UpdateResult::Conflict(id),
                Ok(true) => match self.repository.find_by_id(id) {
                    Ok(Some(book)) => UpdateResult::Updated(book),
                    Ok(None) => UpdateResult::Missing(id),
                    Err(e) => UpdateResult::Failure(self.failure(e, request_id)),
                },
                Err(e) => UpdateResult::Failure(self.failure(e, request_id)),
            },
            Err(e) => UpdateResult::Failure(self.failure(e, request_id)),
        }
    }
}

//! 保存層の境界。実装を差し替えても handler / service は変わらない。

use crate::model::Book;
use rusqlite::{params, Connection};
use std::collections::HashMap;
use std::sync::Mutex;

/// 保存層の失敗。内部詳細（SQLやファイルパス）は HTTP 応答へ出さず、こちらで保持する。
#[derive(Debug)]
pub struct RepositoryError(pub String);

impl std::fmt::Display for RepositoryError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "storage failure")
    }
}

pub trait BookRepository {
    fn find_by_id(&self, id: i64) -> Result<Option<Book>, RepositoryError>;
    fn insert(&self, title: &str) -> Result<Book, RepositoryError>;
    /// version が一致したときだけ更新する（楽観ロック）。成功なら true。
    fn update_title(&self, id: i64, title: &str, expected_version: i64) -> Result<bool, RepositoryError>;
}

/// 依存は rusqlite だけ、プロセスを止めると消える比較用の実装。
pub struct InMemoryBookRepository {
    books: Mutex<HashMap<i64, Book>>,
    sequence: Mutex<i64>,
}

impl InMemoryBookRepository {
    pub fn new() -> Self {
        InMemoryBookRepository { books: Mutex::new(HashMap::new()), sequence: Mutex::new(0) }
    }

    pub fn seed(&self, id: i64, title: &str) -> Result<(), RepositoryError> {
        let book = Book::new(id, title, 1).map_err(RepositoryError)?;
        self.books.lock().unwrap().insert(id, book);
        let mut seq = self.sequence.lock().unwrap();
        *seq = (*seq).max(id);
        Ok(())
    }
}

impl BookRepository for InMemoryBookRepository {
    fn find_by_id(&self, id: i64) -> Result<Option<Book>, RepositoryError> {
        Ok(self.books.lock().unwrap().get(&id).cloned())
    }

    fn insert(&self, title: &str) -> Result<Book, RepositoryError> {
        let id = {
            let mut seq = self.sequence.lock().unwrap();
            *seq += 1;
            *seq
        };
        let book = Book::new(id, title, 1).map_err(RepositoryError)?;
        self.books.lock().unwrap().insert(id, book.clone());
        Ok(book)
    }

    fn update_title(&self, id: i64, title: &str, expected_version: i64) -> Result<bool, RepositoryError> {
        let mut books = self.books.lock().unwrap();
        match books.get_mut(&id) {
            Some(current) if current.version == expected_version => {
                current.title = title.trim().to_string();
                current.version += 1;
                Ok(true)
            }
            _ => Ok(false),
        }
    }
}

/// SQLite ファイルへ保存する実装。SQL は params! で値を分離し、文字列結合で組み立てない。
pub struct SqliteBookRepository {
    conn: Mutex<Connection>,
}

impl SqliteBookRepository {
    pub fn open(path: &str) -> Result<Self, RepositoryError> {
        let conn = Connection::open(path).map_err(|e| RepositoryError(e.to_string()))?;
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS books (
                id INTEGER PRIMARY KEY, title TEXT NOT NULL, version INTEGER NOT NULL
            );",
        )
        .map_err(|e| RepositoryError(e.to_string()))?;
        Ok(SqliteBookRepository { conn: Mutex::new(conn) })
    }

    pub fn seed(&self, id: i64, title: &str) -> Result<(), RepositoryError> {
        self.conn
            .lock()
            .unwrap()
            .execute("INSERT OR IGNORE INTO books (id, title, version) VALUES (?1, ?2, 1)", params![id, title])
            .map_err(|e| RepositoryError(e.to_string()))?;
        Ok(())
    }
}

impl BookRepository for SqliteBookRepository {
    fn find_by_id(&self, id: i64) -> Result<Option<Book>, RepositoryError> {
        let conn = self.conn.lock().unwrap();
        let mut stmt = conn
            .prepare("SELECT id, title, version FROM books WHERE id = ?1")
            .map_err(|e| RepositoryError(e.to_string()))?;
        let mut rows = stmt
            .query_map(params![id], |row| {
                Ok(Book {
                    id: row.get(0)?,
                    title: row.get(1)?,
                    version: row.get(2)?,
                })
            })
            .map_err(|e| RepositoryError(e.to_string()))?;
        match rows.next() {
            Some(Ok(book)) => Ok(Some(book)),
            Some(Err(e)) => Err(RepositoryError(e.to_string())),
            None => Ok(None),
        }
    }

    fn insert(&self, title: &str) -> Result<Book, RepositoryError> {
        let conn = self.conn.lock().unwrap();
        conn.execute("INSERT INTO books (title, version) VALUES (?1, 1)", params![title])
            .map_err(|e| RepositoryError(e.to_string()))?;
        let id = conn.last_insert_rowid();
        Ok(Book { id, title: title.trim().to_string(), version: 1 })
    }

    fn update_title(&self, id: i64, title: &str, expected_version: i64) -> Result<bool, RepositoryError> {
        // WHERE 句の version 条件が楽観ロック。0件更新は「古い version への同時更新」。
        let changed = self
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE books SET title = ?1, version = version + 1 WHERE id = ?2 AND version = ?3",
                params![title, id, expected_version],
            )
            .map_err(|e| RepositoryError(e.to_string()))?;
        Ok(changed == 1)
    }
}
